# /etc/nginx/conf.d/gray.conf —— 灰度双轨
# 轨道 1：按权重灰度——新版本 v2 先接 10% 流量，放量即调 weight
upstream app_backend {
    server 10.2.0.11:8080 weight=9;   # v1 稳定版
    server 10.2.0.12:8080 weight=1;   # v2 新版本（金丝雀）
}
server {
    listen 80;
    location / {
        proxy_pass http://app_backend;
    }
}
# 轨道 2：按人群灰度（内部员工先行）：基于 cookie 的分裂
upstream canary_pool {
    server 10.2.0.12:8080;            # 金丝雀专用池（成员可与主池重叠）
}
map $cookie_internal $backend_pool {
    "yes"    canary_pool;             # 内部用户进金丝雀
    default  app_backend;             # 其余用户走主池
}
server {
    listen 8081;
    location / {
        # proxy_pass 带变量时，变量值恰为已定义 upstream 名即可直接转发，无需 resolver
        proxy_pass http://$backend_pool;
    }
}

# New-UserOnboarding.ps1 —— 账号开通标准脚本（幂等）
param(
    [Parameter(Mandatory=$true)][string]$Sam,
    [Parameter(Mandatory=$true)][string]$Name,
    [Parameter(Mandatory=$true)][string]$Dept,        # 决定 OU 与默认组
    [Parameter(Mandatory=$true)][string]$TempPwd      # 初始密码（强制首登修改）
)
$ou = switch ($Dept) {
    "Fin"  { "OU=Finance,DC=corp,DC=example,DC=com" }
    "Dev"  { "OU=Dev,DC=corp,DC=example,DC=com" }
    default{ "OU=Staff,DC=corp,DC=example,DC=com" }
}
if (Get-ADUser -Filter "SamAccountName -eq '$Sam'" -ErrorAction SilentlyContinue) {
    Write-Output "EXISTS: $Sam 已存在，跳过（幂等）"; exit 0
}
New-ADUser -Name $Name -SamAccountName $Sam `
    -UserPrincipalName "$Sam@corp.example.com" `
    -Path $ou `
    -AccountPassword (ConvertTo-SecureString $TempPwd -AsPlainText -Force) `
    -ChangePasswordAtLogon $true -Enabled $true
Add-ADGroupMember -Identity "VPN-Users" -Members $Sam      # 默认组按目录项定义
Write-Output "DONE: $Sam @ $ou（执行人 $env:USERNAME 于 $(Get-Date -Format 'F')）"
# 注意：真实部署中 $TempPwd 不应明文出现于命令行历史——由工单系统通过安全通道注入

# 终端磁盘巡检：批量列出使用率 >85% 的终端（脚本输出转请求/工单）
$servers = Get-Content D:\ops\terminal-list.txt
foreach ($t in $servers) {
    $d = Get-CimInstance -ComputerName $t -ClassName Win32_LogicalDisk `
         -Filter "DriveType=3 and DeviceID='C:'" -ErrorAction SilentlyContinue
    if ($d) {
        $pct = [math]::Round(100 * (1 - $d.FreeSpace / $d.Size), 0)
        if ($pct -gt 85) { "$t C: ${pct}% — 建议清理或扩容请求" }
    }
}

